def filter_by_word(strings: List[str], word: str) -> List[str]:
    """ Filter an input list of strings only for ones that contain given word
    >>> filter_by_word([], 'a')
    []
    >>> filter_by_word(['apple', 'caterpillar', 'banana', 'car', 'cart'], 'a')
    ['apple', 'caterpillar', 'car']
    """
    result = []
    for each_string in strings:
        if word in each_string:
            result.append(each_string)
    return result

def filter_by_prefix(strings: List[str], prefix: str) -> List[str]:
    """ Filter an input list of strings only for ones that start with a given prefix
    >>> filter_by_prefix([], 'a')
    []
    >>> filter_by_prefix(['apple', 'caterpillar', 'banana', 'car', 'cart'], 'a')
    ['apple', 'caterpillar', 'car']
    """
    result = []
    for each_string in strings:
        if each_string.startswith(prefix):
            result.append(each_string)
    return result

