def get_max_depth(paren_string: str) -> int:
    """ Parse an expression and extract depth information to return the maximum nesting depth"""
    current_depth = 0

    if '(' not in paren_string:
        return current_depth
    for i, par in enumerate(paren_string):

        if par == ')':
            current_depth = max(current_depth, get_max_depth(paren_string[i+1:]))

    return current_depth


